CREATE TABLE phonepe_payment_attempts (merchant_order_id VARCHAR(63) PRIMARY KEY,booking_id INT NOT NULL,user_id INT NOT NULL,phonepe_order_id VARCHAR(100),phonepe_transaction_id VARCHAR(100),amount_paisa BIGINT NOT NULL,state VARCHAR(30) NOT NULL DEFAULT 'PENDING',response_payload JSON NULL,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY (booking_id) REFERENCES bookings(booking_id) ON DELETE CASCADE,FOREIGN KEY (user_id) REFERENCES users(user_id) ON DELETE CASCADE);
